#include <vector>
using namespace std;

class Solution {
public:
    vector<int> mostCompetitive(vector<int>& nums, int k) {
        vector<int> stack;
        int n = nums.size();
        for (int i = 0; i < n; ++i) {
            int x = nums[i];
            while (!stack.empty() && stack.back() > x && (int)stack.size() + (n - i) > k) {
                stack.pop_back();
            }
            if ((int)stack.size() < k) {
                stack.push_back(x);
            }
        }
        return stack;
    }
};

import java.util.*;

class Solution {
    public int[] mostCompetitive(int[] nums, int k) {
        int[] stack = new int[k];
        int top = -1;
        int n = nums.length;
        for (int i = 0; i < n; ++i) {
            int x = nums[i];
            while (top >= 0 && stack[top] > x && (top + 1) + (n - i) > k) {
                top--;
            }
            if (top + 1 < k) {
                stack[++top] = x;
            }
        }
        return stack;
    }
}

/**
 * @param {number[]} nums
 * @param {number} k
 * @return {number[]}
